import gzip,glob,csv,io
def meta(f):
    rows=[]
    for l in gzip.open(f,'rt',errors='replace'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith('!Sample_'): rows.append(next(csv.reader([l.rstrip('\n')],delimiter='\t')))
    return rows
